  id: string;
  fullName: string;
  memberships: Membership[];
};

/**
 * The signed-in person and their brands, or null without a session. Cached for
 * the duration of one request only (React cache), never across users.
 *
 * getUser() validates the token with Supabase Auth instead of trusting the
 * cookie as getSession() would.
 */
export const getOptionalUser = cache(async (): Promise<CurrentUser | null> => {
  const supabase = await createClient();
  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) return null;

  const [profile, memberships] = await Promise.all([
    supabase.from("profiles").select("full_name").eq("id", user.id).single(),
    supabase
      .from("brand_memberships")
      .select("role, brand:brands!inner(id, slug, name)")
      .eq("user_id", user.id)
      .order("brand(name)"),
  ]);
  if (profile.error) throw profile.error;
  if (memberships.error) throw memberships.error;

  return {
    id: user.id,
    fullName: profile.data.full_name,
    memberships: memberships.data.map((m) => ({
      brandId: m.brand.id,
      slug: m.brand.slug,
      name: m.brand.name,
      role: m.role as BrandRole,
    })),
  };
});

/** The signed-in person; throws UnauthorizedError (401) without a session. */
export async function getCurrentUser(): Promise<CurrentUser> {
  const user = await getOptionalUser();
  if (!user) throw new UnauthorizedError();
  return user;
}

/**
 * The caller's membership in the brand with this slug. A brand that does not
 * exist and a brand the caller is not a member of both throw ForbiddenError, so
 * the answer never reveals which brands exist (TASK-003, Q9).
 */
export function requireMember(user: CurrentUser, brandSlug: string): Membership {
  const membership = user.memberships.find((m) => m.slug === brandSlug);
  if (!membership) throw new ForbiddenError();
  return membership;
}

/**
 * Throws ForbiddenError unless the caller leads this brand. Pass the brand_id
 * read from the database row being acted on, never one taken from the request.
 */
export function requireLeadOf(user: CurrentUser, brandId: string): Membership {
  const membership = user.memberships.find((m) => m.brandId === brandId);
  if (membership?.role !== "lead") throw new ForbiddenError();
  return membership;
}
import "server-only";

/**
 * Typed authorization failures. server/auth throws them; each layer translates
 * them its own way: route handlers answer 401/403, pages call notFound() so a
 * brand's existence is not revealed (TASK-003, Q17).
 */
export class UnauthorizedError extends Error {
  readonly status = 401;
  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

export class ForbiddenError extends Error {
  readonly status = 403;
  constructor(message = "You do not have access to this brand.") {
    super(message);
    this.name = "ForbiddenError";
  }
}

export function isAuthError(error: unknown): error is UnauthorizedError | ForbiddenError {
  return error instanceof UnauthorizedError || error instanceof ForbiddenError;
}
import "server-only";

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { SUPABASE_COOKIE_OPTIONS } from "@/lib/supabase-cookie-options";
import type { Database } from "./database.types";

/**
 * A Supabase client for the current request, authenticated as whoever owns the
 * session cookie. Every query runs with that user's JWT, so RLS always applies.
 * There is deliberately no service_role client anywhere in the app.
 *
 * Create one per request (never share it at module level): it carries that
 * request's cookies.
 */
export async function createClient() {
  const cookieStore = await cookies();

  return createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookieOptions: SUPABASE_COOKIE_OPTIONS,
      cookies: {
        getAll() {
          return cookieStore.getAll();
        },
        setAll(cookiesToSet) {
          try {
            for (const { name, value, options } of cookiesToSet) {
              cookieStore.set(name, value, options);
            }
          } catch {
            // Server Components cannot set cookies. The proxy refreshes the
            // session on every request, so a refresh lost here is not needed.
          }
        },
      },
    },
  );
}
    or private.authored_reply_in_led_brand(id)
  );

-- A specialist sees their own replies in every brand; a lead sees every reply of
-- the brands they lead. Nobody sees a reply only because they share a brand
-- with its author.
create policy replies_select on public.replies
  for select to authenticated
  using (specialist_id = (select auth.uid()) or private.is_lead_of(brand_id));

-- The subquery on replies runs under the replies policy, which is fine: the
-- author can see their own reply, so this adds no access.
create policy reviews_select on public.reviews
  for select to authenticated
  using (
    private.is_lead_of(brand_id)
    or exists (
      select 1 from public.replies r
      where r.id = reply_id and r.specialist_id = (select auth.uid())
    )
  );

-- Delegates to the reviews policy: an issue is visible exactly when its review is.
create policy review_issues_select on public.review_issues
  for select to authenticated
  using (exists (select 1 from public.reviews rv where rv.id = review_id));

-- The issue catalog is the same for every brand and holds no tenant data, so any
-- signed-in user may read it. It is the only unconditional policy in the schema.
create policy issue_types_select on public.issue_types
  for select to authenticated
  using (true);

create policy brand_events_select on public.brand_events
  for select to authenticated
  using (private.is_member_of(brand_id));

-- ---------------------------------------------------------------------------
-- Write policies
-- ---------------------------------------------------------------------------

-- brand_id cannot lie about the reply: the composite foreign key
-- (reply_id, brand_id) -> replies (id, brand_id) rejects a mismatch, so checking
-- is_lead_of(brand_id) here is checking the reply's real brand.
create policy reviews_insert on public.reviews
  for insert to authenticated
  with check (reviewer_id = (select auth.uid()) and private.is_lead_of(brand_id));

-- Only your own review, and only while you still lead the brand. The column
-- grant above already keeps reply_id, brand_id and reviewer_id from changing.
create policy reviews_update on public.reviews
  for update to authenticated
  using (reviewer_id = (select auth.uid()) and private.is_lead_of(brand_id))
  with check (reviewer_id = (select auth.uid()) and private.is_lead_of(brand_id));

-- Retired issue types (active = false) stay on old reviews but cannot be added
-- to new ones.
create policy review_issues_insert on public.review_issues
  for insert to authenticated
  with check (
    exists (
      select 1 from public.reviews rv
      where rv.id = review_id
        and rv.reviewer_id = (select auth.uid())
        and private.is_lead_of(rv.brand_id)
    )
    and exists (
      select 1 from public.issue_types it
      where it.code = issue_code and it.active
    )
  );

create policy review_issues_delete on public.review_issues
  for delete to authenticated
  using (
    exists (
      select 1 from public.reviews rv
      where rv.id = review_id
        and rv.reviewer_id = (select auth.uid())
        and private.is_lead_of(rv.brand_id)
    )
  );

-- updated_at is not in the column grant, so the app cannot set it; a trigger
-- keeps it true on every edit.
create function private.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

create trigger reviews_touch_updated_at
  before update on public.reviews
  for each row execute function private.touch_updated_at();
