import type { Metadata } from "next";
import { Bricolage_Grotesque, Instrument_Sans, JetBrains_Mono } from "next/font/google";
import { AppShell } from "@/ui/app-shell";
import "./globals.css";

const instrumentSans = Instrument_Sans({
  variable: "--font-instrument-sans",
  subsets: ["latin"],
});

const bricolage = Bricolage_Grotesque({
  variable: "--font-bricolage",
  subsets: ["latin"],
  weight: ["600", "700"],
});

const jetbrainsMono = JetBrains_Mono({
  variable: "--font-jetbrains-mono",
  subsets: ["latin"],
  weight: ["400", "500"],
});

export const metadata: Metadata = {
  title: "Sellervate QA",
  description: "Review sent support replies and read the feedback on your own.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html
      lang="en"
      className={`${instrumentSans.variable} ${bricolage.variable} ${jetbrainsMono.variable} h-full antialiased`}
    >
      <body className="min-h-full">
        <AppShell>{children}</AppShell>
      </body>
    </html>
  );
}
import { demoPeopleOptions } from "@/features/session/current-person";
import { PersonPicker } from "@/features/session/person-picker";
import { isDemoLoginEnabled } from "@/server/auth/demo-users";
import { getOptionalUser } from "@/server/auth/session";
import { EmptyState } from "@/ui/empty-state";

// Every brand in the seed, including ones the current person cannot see, so the
// API links below show both the 200 and the 403.
const SEED_BRAND_SLUGS = ["voltra", "boxwell", "hebra"];

export default async function HomePage() {
  const user = await getOptionalUser();

  if (!user) {
    if (!isDemoLoginEnabled()) {
      return (
        <EmptyState
          title="Demo sign-in is disabled"
          description="Add DEMO_USER_PASSWORD to apps/web/.env.local (see .env.example) and restart pnpm dev."
        />
      );
    }
    return (
      <section className="flex flex-col gap-6">
        <header className="flex flex-col gap-2">
          <h1 className="font-display text-2xl font-bold tracking-tight">Choose a person</h1>
          <p className="max-w-prose text-sm text-ink-muted">
            Sign-in is simulated; access is not. Each person sees only what their role in each brand allows,
            and the server enforces it.
          </p>
        </header>
        <PersonPicker people={demoPeopleOptions()} />
      </section>
    );
  }

  return (
    <section className="flex flex-col gap-8">
      <header className="flex flex-col gap-2">
        <h1 className="font-display text-2xl font-bold tracking-tight">Hi, {user.fullName.split(" ")[0]}</h1>
        <p className="max-w-prose text-sm text-ink-muted">
          The review queue and feedback screens are on their way. For now, this is what the server grants you.
        </p>
      </header>

      {user.memberships.length === 0 ? (
        <EmptyState title="No brands yet" description="Ask a lead to add you to a brand." />
      ) : (
        <ul className="divide-y divide-line rounded-lg border border-line bg-surface">
          {user.memberships.map((m) => (
            <li key={m.brandId} className="flex items-center justify-between px-5 py-3">
              <span className="font-medium">{m.name}</span>
              <span className="font-mono text-2xs uppercase tracking-widest text-ink-muted">{m.role}</span>
            </li>
          ))}
        </ul>
      )}

      <div className="flex flex-col gap-2">
        <h2 className="text-sm font-semibold">Check the API</h2>
        <p className="text-sm text-ink-muted">A brand you are not part of answers 403.</p>
        <ul className="flex flex-wrap gap-2">
          {SEED_BRAND_SLUGS.map((slug) => (
            <li key={slug}>
              <a
                href={`/api/brands/${slug}/replies`}
                className="inline-block rounded-md border border-line bg-surface px-3 py-1.5 font-mono text-xs text-accent hover:border-accent"
              >
                /api/brands/{slug}/replies
              </a>
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}
import Link from "next/link";
import type { ReactNode } from "react";
import { currentPersonOption, demoPeopleOptions } from "@/features/session/current-person";
import { UserSwitcher } from "@/features/session/user-switcher";
import { isDemoLoginEnabled } from "@/server/auth/demo-users";
import { getOptionalUser } from "@/server/auth/session";

/** Top-level frame: brand mark on the left, the user switcher on the right. */
export async function AppShell({ children }: { children: ReactNode }) {
  const user = await getOptionalUser();

  return (
    <div className="flex min-h-screen flex-col">
      <header className="sticky top-0 z-10 border-b border-line bg-surface/90 backdrop-blur">
        <div className="mx-auto flex h-14 max-w-6xl items-center justify-between gap-4 px-4 sm:px-6">
          <Link href="/" className="flex shrink-0 items-baseline gap-2">
            <span className="font-display text-base font-bold tracking-tight">Sellervate</span>
            <span className="font-mono text-2xs uppercase tracking-widest text-ink-muted">QA</span>
          </Link>
          <UserSwitcher
            people={demoPeopleOptions()}
            current={currentPersonOption(user)}
            enabled={isDemoLoginEnabled()}
          />
        </div>
      </header>
      <main className="mx-auto w-full max-w-6xl flex-1 px-4 py-8 sm:px-6">{children}</main>
    </div>
  );
}
@import "tailwindcss";

/*
 * Design tokens.
 *
 * Colour: sage-tinted neutrals so the page reads calm for long reading sessions,
 * and one ink-blue accent (the reviewer's pen) reserved for actions and selection.
 * Semantic colours (good / warn / bad) encode review outcomes and issue severity
 * and are never used as decoration.
 *
 * Type: Instrument Sans for UI and the replies being read, Bricolage Grotesque for
 * the few headings, JetBrains Mono for scores, dates and ticket ids.
 * Scale (rem): 0.75 / 0.8125 / 0.875 / 1 / 1.25 / 1.5 / 2.
 */
:root {
  --ground: #f4f5f2;
  --surface: #ffffff;
  --sunken: #eceee9;
  --ink: #16201c;
  --ink-muted: #5b6660;
  --line: #dce1da;
  --line-strong: #c3cac1;

  --accent: #2f4bc6;
  --accent-ink: #ffffff;
  --accent-soft: #e7ebfb;

  --good: #1d7a4b;
  --good-soft: #e3f2e9;
  --warn: #a8690f;
  --warn-soft: #fbf0dc;
  --bad: #b3261e;
  --bad-soft: #fbe6e4;
}

@media (prefers-color-scheme: dark) {
  :root {
    color-scheme: dark;
    --ground: #101412;
    --surface: #181d1b;
    --sunken: #0c0f0e;
    --ink: #e6ebe7;
    --ink-muted: #9ba69f;
    --line: #2b3430;
    --line-strong: #3a4540;

    --accent: #93a5ff;
    --accent-ink: #0d1330;
    --accent-soft: #1f2544;

    --good: #5fcb93;
    --good-soft: #15291f;
    --warn: #e3aa52;
    --warn-soft: #2e2412;
    --bad: #f08a82;
    --bad-soft: #321816;
  }
}

@theme inline {
  --color-ground: var(--ground);
  --color-surface: var(--surface);
  --color-sunken: var(--sunken);
  --color-ink: var(--ink);
  --color-ink-muted: var(--ink-muted);
  --color-line: var(--line);
  --color-line-strong: var(--line-strong);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-soft: var(--accent-soft);
  --color-good: var(--good);
  --color-good-soft: var(--good-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-bad: var(--bad);
  --color-bad-soft: var(--bad-soft);

  --font-sans: var(--font-instrument-sans), ui-sans-serif, system-ui, sans-serif;
  --font-display: var(--font-bricolage), var(--font-instrument-sans), ui-sans-serif, sans-serif;
  --font-mono: var(--font-jetbrains-mono), ui-monospace, "Cascadia Mono", monospace;

  --text-2xs: 0.75rem;
  --text-2xs--line-height: 1rem;
  --text-xs: 0.8125rem;
  --text-xs--line-height: 1.125rem;
  --text-sm: 0.875rem;
  --text-sm--line-height: 1.375rem;
  --text-base: 1rem;
  --text-base--line-height: 1.625rem;
  --text-lg: 1.25rem;
  --text-lg--line-height: 1.75rem;
  --text-xl: 1.5rem;
  --text-xl--line-height: 2rem;
  --text-2xl: 2rem;
  --text-2xl--line-height: 2.375rem;
}

@layer base {
  body {
    background: var(--ground);
    color: var(--ink);
    font-family: var(--font-sans);
  }

  h1,
  h2,
  h3 {
    font-family: var(--font-display);
    text-wrap: balance;
    letter-spacing: -0.01em;
  }

  :focus-visible {
    outline: 2px solid var(--accent);
    outline-offset: 2px;
  }
}

