  const start = currentId ? items.findIndex((i) => i.id === currentId) + 1 : 0;
  const ordered = [...items.slice(start), ...items.slice(0, start)];
  return ordered.find((i) => i.myScore === null && i.id !== currentId) ?? null;
}

