  martaDirectInsert: (await fetch(`${url}/rest/v1/reviews`, { method: "POST", headers: h(marta), body: JSON.stringify({ reply_id: vol.id, brand_id: vol.brand_id, reviewer_id: "a0000000-0000-4000-8000-000000000001", score: 5 }) })).status,
  martaCriticalWith5: await call(marta, { p_reply_id: vol.id, p_score: 5, p_comment: "", p_issue_codes: ["wrong_info"] }),
  nuriaOnVoltra: await call(nuria, { p_reply_id: vol.id, p_score: 1, p_comment: "", p_issue_codes: [] }),
  anon: (await fetch(`${url}/rest/v1/rpc/save_review`, { method: "POST", headers: { apikey: key, "content-type": "application/json" }, body: JSON.stringify({ p_reply_id: vol.id, p_score: 1, p_comment: "", p_issue_codes: [] }) })).status,
  martaValid: await call(marta, { p_reply_id: vol.id, p_score: 4, p_comment: "HTTP check", p_issue_codes: ["tone"] }),
};
console.log(JSON.stringify(out, null, 2));
EOF
