45	// The message of a mapped failure reaches the user as is. The migration keeps
46	// them static; interpolating an id or any row data there would leak it.
47	const FAILURE_BY_CODE: Record<string, SaveReviewFailure> = {
48	  PT404: "not_found",
49	  "42501": "forbidden",
50	  "22023": "invalid",
51	};
52	
53	/**
54	 * Writes the caller's review and its issues in one transaction. The function
55	 * derives brand_id from the reply and reviewer_id from the session, so neither
56	 * travels in the request.

1	-- How many rows of each table every seed person sees through RLS, plus the
2	-- writes that must be rejected. Run by hand against the local database:
3	--
4	--   docker exec -i supabase_db_sellervate-qa psql -U postgres -d postgres < supabase/tests/rls-matrix.sql
5	--
6	-- Each block impersonates one person exactly as PostgREST does: role
7	-- authenticated and the user id in request.jwt.claims. Everything runs in a
8	-- transaction that is rolled back, so it leaves the database untouched.
9	--
10	-- Not a pgTAP suite (see DECISIONS.md); the expected numbers are written next
11	-- to the output in the TASK-003 pull request.
12	
13	begin;
14	
15	create temporary table rls_matrix (person text, brands int, memberships int, profiles int,
16	  replies int, reviews int, review_issues int, issue_types int, brand_events int,
17	  hebra_replies int, foreign_replies int);
18	grant all on rls_matrix to authenticated;
19	
20	create function pg_temp.check_person(person text, uid uuid) returns void language plpgsql as $$
21	begin
22	  perform set_config('request.jwt.claims', json_build_object('sub', uid, 'role', 'authenticated')::text, true);
23	  set local role authenticated;
24	  insert into rls_matrix select
25	    person,
26	    (select count(*) from public.brands),
27	    (select count(*) from public.brand_memberships),
28	    (select count(*) from public.profiles),
29	    (select count(*) from public.replies),
30	    (select count(*) from public.reviews),
31	    (select count(*) from public.review_issues),
32	    (select count(*) from public.issue_types),
33	    (select count(*) from public.brand_events),
34	    (select count(*) from public.replies r join public.brands b on b.id = r.brand_id where b.slug = 'hebra'),
35	    -- Replies visible to this person that they neither wrote nor lead: must be 0.
36	    (select count(*) from public.replies r
37	      where r.specialist_id <> uid
38	        and not exists (select 1 from public.brand_memberships m
39	                        where m.user_id = uid and m.brand_id = r.brand_id and m.role = 'lead'));
40	  reset role;
41	end;
42	$$;
43	
44	select pg_temp.check_person('marta', 'a0000000-0000-4000-8000-000000000001');
45	select pg_temp.check_person('nuria', 'a0000000-0000-4000-8000-000000000002');
46	select pg_temp.check_person('dani',  'a0000000-0000-4000-8000-000000000003');
47	select pg_temp.check_person('leo',   'a0000000-0000-4000-8000-000000000004');
48	select pg_temp.check_person('sara',  'a0000000-0000-4000-8000-000000000005');
49	
50	-- anon (no session) has no table privileges at all.
51	set local role anon;
52	do $$
53	begin
54	  perform count(*) from public.replies;
55	  raise exception 'FAIL: anon read replies';
56	exception when insufficient_privilege then
57	  raise notice 'ok: anon cannot read replies';
58	end $$;
59	reset role;
60	
61	select * from rls_matrix;
62	
63	-- Writes that must fail -------------------------------------------------------
64	
65	-- Nuria (lead of Hebra only) reviews a Voltra reply. RLS already hides Voltra
66	-- replies from her, so take the ids as the superuser, as if they had leaked.
67	do $$
68	declare
69	  voltra_reply uuid;
70	  voltra_brand uuid;
71	begin
72	  select r.id, r.brand_id into voltra_reply, voltra_brand
