const html = await (await fetch('/review')).text();
const doc = new DOMParser().parseFromString(html, 'text/html');
const links = [...doc.querySelectorAll('main ol a')].map(a => ({href: a.getAttribute('href'), text: a.textContent}));
const vol51 = links.find(l => l.text.includes('VOL-48651'));
const vol44 = links.find(l => l.text.includes('VOL-48644'));
const header = doc.querySelector('main p.font-mono')?.textContent;
const id51 = new URL(vol51.href, location.origin).searchParams.get('reply');
const id44 = new URL(vol44.href, location.origin).searchParams.get('reply');
const martaDetail = await (await fetch('/replies/' + id44)).text();
await login('dani');
const daniDetail = await (await fetch('/replies/' + id44)).text();
await login('marta');
({header, sentTimes: links.map(l => l.text.match(/Sent (\d\d:\d\d)/)?.[1]), martaSeesReview: martaDetail.includes('Reviewed '), daniSeesReview: daniDetail.includes('Reviewed '), id51})

