const chip = (t) => [...document.querySelectorAll('form label')].find(l => l.textContent.includes(t));
radio(5).click(); await wait(100); const a = checked();
chip('Did not check the order history').click(); await wait(100); const b = checked();
document.querySelector('form button[type=submit]').click(); await wait(600);
const alerts = [...document.querySelectorAll('[role=alert]')].map(x => x.textContent);
radio(1).click(); await wait(100);
document.querySelector('form button[type=submit]').click(); await wait(2500);
({after5: a, afterCritical: b, alertsOnEmptySave: alerts, afterSave: document.querySelector('[aria-label="Customer message"] p')?.textContent, header: document.querySelector('main p.font-mono')?.textContent})

